{"file_path":"src/errors.js","content":"/**
 * The error raised when the input does not scan. Carries the position where
 * the failure was detected so the CLI can format `error: <line>:<column>: <reason>`.
 */
export class ScanError extends Error {
  constructor(reason, line, column) {
    super(reason)
    this.name = 'ScanError'
    this.reason = reason
    this.line = line
    this.column = column
  }
}
"}

