chunk.argumentsDelta:
{"file_path":"src/cursor.js","content":"/**
 * A position-tracking cursor over the source text's code points. Reading a
 * line feed moves to the next line and resets the column to 1; reading a tab
 * advances the column to the next multiple of 4 plus 1; every other code
 * point advances the column by 1.
 */
export class Cursor {
  constructor(source) {
    this.chars = Array.from(source)
    this.index = 0
    this.line = 1
    this.column = 1
  }

  eof() {
    return this.index >= this.chars.length
  }

  current() {
    return this.chars[this.index]
  }

  peek(offset) {
    return this.chars[this.index + offset]
  }

  pos() {
    return { line: this.line, column: this.column }
  }

  consume() {
    const c = this.chars[this.index]
    this.index++
    if (c === '\n') {
      this.line++
      this.column = 1
    } else if (c === '\t') {
      this.column = (Math.floor((this.column - 1) / 4) + 1) * 4 + 1
    } else {
      this.column++
    }
    return c
  }
}
"}

