chunk.argumentsDelta:
{"file_path":"src/lexer.js","content":"/**
 * The scanner. `scan(source)` turns UTF-8 source text into a list of tokens,
 * `{ kind, text, line, column }`, or throws a `ScanError` at the first point
 * the input does not conform to the language's grammar.
 */
import { Cursor } from './cursor.js'
import { ScanError } from './errors.js'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const isIdentStart = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isIdentCont = (c) => c !== undefined && /^[A-Za-z0-9_]$/.test(c)
const isDigit = (c) => c !== undefined && /^[0-9]$/.test(c)
const isHexDigit = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== undefined && /^[0-7]$/.test(c)
const isAlnumOrUnderscore = (c) => c !== undefined && /^[A-Za-z0-9_]$/.test(c)

function fail(reason, pos) {
  throw new ScanError(reason, pos.line, pos.column)
}

/**
 * Consumes a run of digits (as recognised by `isDigitFn`), allowing a single
 * `_` between two digits of the run and nowhere else. Returns the number of
 * digits consumed (not counting underscores).
 */
function consumeDigitRun(cursor, isDigitFn) {
  let count = 0
  while (!cursor.eof()) {
    if (isDigitFn(cursor.current())) {
      cursor.consume()
      count++
      continue
    }
    if (cursor.current() === '_' && count > 0 && isDigitFn(cursor.peek(1))) {
      cursor.consume()
      continue
    }
    break
  }
  return count
}

function consumeTrailingRun(cursor) {
  let consumed = false
  while (!cursor.eof() && isAlnumOrUnderscore(cursor.current())) {
    cursor.consume()
    consumed = true
  }
  return consumed
}

function scanNumber(cursor, startPos, startIndex) {
  const first = cursor.consume()
  let digitsFound = 1

  if (first === '0' && !cursor.eof() && /^[xXbBoO]$/.test(cursor.current())) {
    const marker = cursor.consume().toLowerCase()
    const isDigitFn = marker === 'x' ? isHexDigit : marker === 'b' ? isBinDigit : isOctDigit
    digitsFound = consumeDigitRun(cursor, isDigitFn)
  } else {
    consumeDigitRun(cursor, isDigit)

    if (cursor.current() === '.' && isDigit(cursor.peek(1))) {
      cursor.consume()
      consumeDigitRun(cursor, isDigit)
    }

    if (!cursor.eof() && /^[eE]$/.test(cursor.current())) {
      const afterMarker = cursor.peek(1)
      const isSign = afterMarker === '+' || afterMarker === '-'
      const digitAfter = isSign ? cursor.peek(2) : afterMarker
      if (isDigit(digitAfter)) {
        cursor.consume()
        if (isSign) cursor.consume()
        consumeDigitRun(cursor, isDigit)
      }
    }
  }

  const trailing = consumeTrailingRun(cursor)
  const text = cursor.chars.slice(startIndex, cursor.index).join('')
  if (digitsFound === 0 || trailing) {
    fail(`invalid number ${text}`, startPos)
  }
  return { kind: 'number', text, line: startPos.line, column: startPos.column }
}

function scanIdent(cursor, startPos) {
  let text = ''
  while (!cursor.eof() && isIdentCont(cursor.current())) {
    text += cursor.consume()
  }
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, text, line: startPos.line, column: startPos.column }
}

function scanString(cursor, startPos) {
  cursor.consume() // opening quote
  let value = ''
  for (;;) {
    if (cursor.eof()) fail('unterminated string', startPos)
    const c = cursor.current()
    if (c === '"') {
      cursor.consume()
      break
    }
    if (c === '\n') fail('newline in string', cursor.pos())
    if (c === '\\') {
      const bsPos = cursor.pos()
      cursor.consume()
      if (cursor.eof()) fail('unterminated string', startPos)
      const e = cursor.current()
      if (e === '\n') fail('newline in string', cursor.pos())
      switch (e) {
        case 'n':
          value += '\n'
          cursor.consume()
          break
        case 't':
          value += '\t'
          cursor.consume()
          break
        case 'r':
          value += '\r'
          cursor.consume()
          break
        case '\\':
          value += '\\'
          cursor.consume()
          break
        case '"':
          value += '"'
          cursor.consume()
          break
        case '0':
          value += '\0'
          cursor.consume()
          break
        case 'x': {
          cursor.consume()
          let hex = ''
          for (let k = 0; k < 2; k++) {
            if (cursor.eof()) fail('unterminated string', startPos)
            if (cursor.current() === '\n') fail('newline in string', cursor.pos())
            if (!isHexDigit(cursor.current())) fail('invalid escape \\x', bsPos)
            hex += cursor.consume()
          }
          value += String.fromCharCode(parseInt(hex, 16))
          break
        }
        case 'u': {
          cursor.consume()
          if (cursor.eof()) fail('unterminated string', startPos)
          if (cursor.current() !== '{') fail('invalid escape \\u', bsPos)
          cursor.consume()
          let hex = ''
          for (;;) {
            if (cursor.eof()) fail('unterminated string', startPos)
            if (cursor.current() === '\n') fail('newline in string', cursor.pos())
            if (cursor.current() === '}') {
              cursor.consume()
              break
            }
            if (!isHexDigit(cursor.current())) fail('invalid escape \\u', bsPos)
            hex += cursor.consume()
          }
          if (hex.length === 0) fail('invalid escape \\u', bsPos)
          const codePoint = parseInt(hex, 16)
          if (codePoint > 0x10ffff) fail('invalid escape \\u', bsPos)
          value += String.fromCodePoint(codePoint)
          break
        }
        default:
          fail(`invalid escape \\${e}`, bsPos)
      }
    } else {
      value += cursor.consume()
    }
  }
  return { kind: 'string', text: JSON.stringify(value), line: startPos.line, column: startPos.column }
}

function scanRawString(cursor, startPos) {
  cursor.consume() // 'r'
  cursor.consume() // opening quote
  let value = ''
  for (;;) {
    if (cursor.eof()) fail('unterminated string', startPos)
    const c = cursor.current()
    if (c === '"') {
      cursor.consume()
      break
    }
    value += cursor.consume()
  }
  return { kind: 'rawstring', text: JSON.stringify(value), line: startPos.line, column: startPos.column }
}

function skipWhitespaceAndComments(cursor) {
  for (;;) {
    if (cursor.eof()) return
    const c = cursor.current()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      cursor.consume()
      continue
    }
    if (c === '/' && cursor.peek(1) === '/') {
      cursor.consume()
      cursor.consume()
      while (!cursor.eof() && cursor.current() !== '\n') cursor.consume()
      continue
    }
    if (c === '/' && cursor.peek(1) === '*') {
      const startPos = cursor.pos()
      cursor.consume()
      cursor.consume()
      let depth = 1
      while (depth > 0) {
        if (cursor.eof()) fail('unterminated block comment', startPos)
        if (cursor.current() === '/' && cursor.peek(1) === '*') {
          depth++
          cursor.consume()
          cursor.consume()
          continue
        }
        if (cursor.current() === '*' && cursor.peek(1) === '/') {
          depth--
          cursor.consume()
          cursor.consume()
          continue
        }
        cursor.consume()
      }
      continue
    }
    return
  }
}

/** Scans `source` fully, returning its tokens or throwing a `ScanError`. */
export function scan(source) {
  const cursor = new Cursor(source)
  const tokens = []
  for (;;) {
    skipWhitespaceAndComments(cursor)
    if (cursor.eof()) break
    const startPos = cursor.pos()
    const startIndex = cursor.index
    const c = cursor.current()
    if (isIdentStart(c)) {
      tokens.push(scanIdent(cursor, startPos))
      continue
    }
    if (isDigit(c)) {
      tokens.push(scanNumber(cursor, startPos, startIndex))
      continue
    }
    if (c === '"') {
      tokens.push(scanString(cursor, startPos))
      continue
    }
    if (c === 'r' && cursor.peek(1) === '"') {
      tokens.push(scanRawString(cursor, startPos))
      continue
    }
    const two = c + (cursor.peek(1) ?? '')
    if (TWO_CHAR_PUNCT.has(two)) {
      cursor.consume()
      cursor.consume()
      tokens.push({ kind: 'punct', text: two, line: startPos.line, column: startPos.column })
      continue
    }
    if (ONE_CHAR_PUNCT.has(c)) {
      cursor.consume()
      tokens.push({ kind: 'punct', text: c, line: startPos.line, column: startPos.column })
      continue
    }
    fail(`unexpected character ${c}`, startPos)
  }
  return tokens
}
"}

