const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const isIdentStart = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isIdentCont = (c) => c !== undefined && /^[A-Za-z0-9_]$/.test(c)
const isDigit = (c) => c !== undefined && /^[0-9]$/.test(c)
const isHexDigit = (c) => c !== undefined && /^[0-9A-Fa-f]$/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== undefined && /^[0-7]$/.test(c)
const isAlnumOrUnderscore = (c) => c !== undefined && /^[A-Za-z0-9_]$/.test(c)

function fail(reason, pos) {
  throw new ScanError(reason, pos.line, pos.column)
}

/**
 * Consumes a run of digits (as recognised by `isDigitFn`), allowing a single
 * `_` between two digits of the run and nowhere else. Returns the number of
 * digits consumed (not counting underscores).
 */
function consumeDigitRun(cursor, isDigitFn) {
  let count = 0
  while (!cursor.eof()) {
    if (isDigitFn(cursor.current())) {
      cursor.consume()
      count++
      continue
    }
    if (cursor.current() === '_' && count > 0 && isDigitFn(cursor.peek(1))) {
      cursor.consume()
      continue
    }
    break
  }
  return count
}

function consumeTrailingRun(cursor) {
  let consumed = false
  while (!cursor.eof() && isAlnumOrUnderscore(cursor.current())) {
    cursor.consume()
    consumed = true
  }
  return consumed
}

