{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import { scan } from './lexer.js'
import { ScanError } from './errors.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  // eslint-disable-next-line no-constant-condition
  while (true) {
    let bytesRead
    try {
      bytesRead = require('node:fs').readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readStdin()

  let tokens
  try {
    tokens = scan(source)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.line}:${err.column}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  let out = ''
  if (mode === 'tokens') {
    for (const t of tokens) {
      out += `${t.line}:${t.column} ${t.kind} ${t.text}\n`
    }
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    for (const k of STAT_KINDS) {
      out += `${k} ${counts[k]}\n`
    }
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

